import { CORRECTED_EVERYDAY_EXAMPLES } from "../../core/everyday-presets";
import { parseCharacterConfig } from "../../core/config";
import type { ArtV6CharacterConfig } from "../../core/types";

export const SOURCE_REVISION = "ea01dd8e074741fdfab0311e1e64585329c29391";
export interface RigKeyframe {
  footX: number;
  footLift: number;
  shoePitch: number;
  bodyBob: number;
  armAngle: number;
  lean: number;
}
/** A recipe, not a Spine file. Mesh topology/weights are generated by this
 * version's fixed algorithm from the frozen, registered source attachments. */
export interface RigProject {
  format: "gathria-skeletal-project";
  schemaVersion: 1;
  sourceRevision: string;
  config: ArtV6CharacterConfig;
  mesh: { blendRadius: number; volume: number };
  timeline: { fps: 18; frames: RigKeyframe[] };
}

export function createDefaultProject(): RigProject {
  const footX = [12, 0, -13, -25, -27, -25, -20, -12, 0, 10, 16, 16];
  const footLift = [0, 0, 0, 10, 24, 34, 36, 30, 22, 14, 6, 2];
  const shoePitch = [0, 0, 0, 0.18, 0.4, 0.48, 0.38, 0.2, 0.05, -0.1, -0.08, 0];
  const bodyBob = [2, 4, 2, -1, -2, 0];
  const armAngle = [
    -0.16, 0.16, 0.44, 0.6, 0.6, 0.44, 0.16, -0.16, -0.44, -0.6, -0.6, -0.44,
  ];
  return {
    format: "gathria-skeletal-project",
    schemaVersion: 1,
    sourceRevision: SOURCE_REVISION,
    config: structuredClone(CORRECTED_EVERYDAY_EXAMPLES[0].config),
    mesh: { blendRadius: 6, volume: 0.65 },
    timeline: {
      fps: 18,
      frames: footX.map((x, i) => ({
        footX: x,
        footLift: footLift[i],
        shoePitch: shoePitch[i],
        bodyBob: bodyBob[i % 6],
        armAngle: armAngle[i],
        lean: 0.1,
      })),
    },
  };
}

function object(value: unknown, name: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw Error(`${name} must be an object.`);
  return value as Record<string, unknown>;
}
function bounded(
  value: unknown,
  name: string,
  min: number,
  max: number,
): number {
  if (
    typeof value !== "number" ||
    !Number.isFinite(value) ||
    value < min ||
    value > max
  )
    throw Error(`${name} must be a finite number from ${min} to ${max}.`);
  return value;
}
export function parseRigProject(value: unknown): RigProject {
  const data = object(value, "Rig project");
  if (
    data.format !== "gathria-skeletal-project" ||
    data.schemaVersion !== 1 ||
    data.sourceRevision !== SOURCE_REVISION
  )
    throw Error(
      "Unsupported rig recipe or source revision. Use the Denim v1 project.",
    );
  const config = parseCharacterConfig(data.config);
  const expected = createDefaultProject().config;
  // This first authoring study deliberately binds one identity and wardrobe.
  // A different appearance may need different ownership/weights, not blind reuse.
  if (JSON.stringify(config) !== JSON.stringify(parseCharacterConfig(expected)))
    throw Error(
      "This rig recipe supports the frozen Denim daytrip appearance only.",
    );
  const mesh = object(data.mesh, "mesh");
  const timeline = object(data.timeline, "timeline");
  if (
    timeline.fps !== 18 ||
    !Array.isArray(timeline.frames) ||
    timeline.frames.length !== 12
  )
    throw Error("The Denim trial requires twelve keys at 18 fps.");
  const frames = timeline.frames.map((value, i) => {
    const key = object(value, `frames[${i}]`);
    return {
      footX: bounded(key.footX, "footX", -30, 22),
      footLift: bounded(key.footLift, "footLift", 0, 38),
      shoePitch: bounded(key.shoePitch, "shoePitch", -0.3, 0.6),
      bodyBob: bounded(key.bodyBob, "bodyBob", -4, 6),
      armAngle: bounded(key.armAngle, "armAngle", -0.8, 0.8),
      lean: bounded(key.lean, "lean", 0, 0.18),
    };
  });
  return {
    format: "gathria-skeletal-project",
    schemaVersion: 1,
    sourceRevision: SOURCE_REVISION,
    config: config as ArtV6CharacterConfig,
    mesh: {
      blendRadius: bounded(mesh.blendRadius, "blendRadius", 2, 10),
      volume: bounded(mesh.volume, "volume", 0, 1),
    },
    timeline: { fps: 18, frames },
  };
}
